do $guard$
begin
  if (select count(*) from reviewed_self_host_no) <> 16 then
    raise exception 'N/O review batch must contain sixteen apps';
  end if;
  if (select count(*)
      from reviewed_self_host_no r
      join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid and a.slug=r.item->>'slug'
      where a.published=true
        and a.self_hosting_status='self_hostable'
        and a.name is not distinct from r.item#>>'{current,name}'
        and a.source_code_url is not distinct from r.item#>>'{current,source_code_url}'
        and a.docker_image is not distinct from r.item#>>'{current,docker_image}') <> 16 then
    raise exception 'N/O app snapshot changed since source review';
  end if;
  if exists (
      select 1
      from reviewed_self_host_no r
      cross join lateral jsonb_array_elements_text(r.item#>'{verified,categories}') c(slug)
      left join public.self_host_app_categories cat on cat.slug=c.slug
      where cat.id is null
  ) then
    raise exception 'N/O review contains an unknown directory category';
  end if;
end $guard$;

-- Hide the old Rclone template, archived NadekoBot v5 entry, and mislabeled OBS desktop image.
update public.self_host_apps a set published=false, updated_at=now()
from reviewed_self_host_no r
where a.id=(r.item->>'app_id')::uuid
  and r.item->>'directory_action' like 'unpublish%';

update public.self_host_apps a set
  name=v->>'name',
  summary=v->>'summary',
  summary_source=coalesce(v->>'docs_url',v->>'website_url',v->>'source_code_url'),
  summary_confidence='high',
  website_url=v->>'website_url',
  source_code_url=v->>'source_code_url',
  source_code_host=v->>'source_code_host',
  source_full_name=v->>'source_full_name',
  source_model=(v->>'source_model')::public.self_host_app_source_model,
  source_archived=case when v->>'source_code_host'='github' then (v->>'maintenance_status'='archived') else null end,
  source_checked_at=now(),
  license=v->>'license',
  license_type=(v->>'license_type')::public.self_host_app_license_type,
  license_spdx_id=v->>'license_spdx_id',
  publisher_name=v->>'publisher_name',
  publisher_type=v->>'publisher_type',
  publisher_url=v->>'publisher_url',
  docs_url=v->>'docs_url',
  install_docs_url=v->>'install_docs_url',
  docker_support=v->>'docker_support',
  docker_url=v->>'docker_url',
  docker_image=v->>'docker_image',
  compose_support=nullif(v->>'compose_support','')::boolean,
  compose_url=v->>'compose_url',
  requires_database=nullif(v->>'requires_database','')::boolean,
  database_types=array(select jsonb_array_elements_text(coalesce(v->'database_types','[]'::jsonb))),
  storage_profile=v->>'storage_profile',
  persistent_storage=nullif(v->>'persistent_storage','')::boolean,
  deployment_methods=array(select jsonb_array_elements_text(coalesce(v->'deployment_methods','[]'::jsonb))),
  maintenance_status=v->>'maintenance_status',
  release_version=v->>'release_version',
  release_url=v->>'release_url',
  release_checked_at=now(),
  data_source_urls=array(select jsonb_array_elements_text(r.item->'sources')),
  data_checked_at=now(),
  data_confidence='high',
  technical_facts_checked_at=now(),
  github_owner=case when v->>'source_code_host'='github' then split_part(v->>'source_full_name','/',1) else null end,
  github_repo=case when v->>'source_code_host'='github' then split_part(v->>'source_full_name','/',2) else null end,
  github_full_name=case when v->>'source_code_host'='github' then v->>'source_full_name' else null end,
  github_owner_type=case when v->>'source_code_host'='github' and a.github_full_name=v->>'source_full_name' then a.github_owner_type else null end,
  github_archived=case when v->>'source_code_host'='github' then (v->>'maintenance_status'='archived') else null end,
  github_project_id=case when v->>'source_code_host'='github' and a.github_full_name=v->>'source_full_name' then a.github_project_id else null end,
  technical_fact_status=coalesce(a.technical_fact_status,'{}'::jsonb) || r.item->'technical_fact_status',
  updated_at=now()
from reviewed_self_host_no r
cross join lateral (select r.item->'verified' as v) facts
where a.id=(r.item->>'app_id')::uuid
  and r.item->>'directory_action'='retain';

delete from public.self_host_app_category_links l
using reviewed_self_host_no r
where l.app_id=(r.item->>'app_id')::uuid
  and r.item->>'directory_action'='retain';

insert into public.self_host_app_category_links(app_id,category_id)
select (r.item->>'app_id')::uuid,c.id
from reviewed_self_host_no r
cross join lateral jsonb_array_elements_text(r.item#>'{verified,categories}') category_slug(slug)
join public.self_host_app_categories c on c.slug=category_slug.slug
where r.item->>'directory_action'='retain';

insert into public.self_host_app_resource_estimates(
  app_id,ram_estimate_min_mb,ram_estimate_max_mb,ram_estimate_kind,ram_estimate_confidence,ram_estimate_basis,ram_source_urls,
  storage_estimate_min_gb,storage_estimate_max_gb,storage_estimate_kind,storage_estimate_confidence,storage_estimate_basis,storage_source_urls,
  checked_at,updated_at
)
select (r.item->>'app_id')::uuid,
  (r.item#>>'{estimates,ram,min_mb}')::numeric,
  (r.item#>>'{estimates,ram,max_mb}')::numeric,
  'estimated',r.item#>>'{estimates,ram,confidence}',r.item#>>'{estimates,ram,basis}',
  array(select jsonb_array_elements_text(r.item#>'{estimates,ram,source_urls}')),
  (r.item#>>'{estimates,storage,min_gb}')::numeric,
  (r.item#>>'{estimates,storage,max_gb}')::numeric,
  'estimated',r.item#>>'{estimates,storage,confidence}',r.item#>>'{estimates,storage,basis}',
  array(select jsonb_array_elements_text(r.item#>'{estimates,storage,source_urls}')),
  now(),now()
from reviewed_self_host_no r
where r.item->>'directory_action'='retain'
on conflict(app_id) do update set
  ram_estimate_min_mb=excluded.ram_estimate_min_mb,
  ram_estimate_max_mb=excluded.ram_estimate_max_mb,
  ram_estimate_kind=excluded.ram_estimate_kind,
  ram_estimate_confidence=excluded.ram_estimate_confidence,
  ram_estimate_basis=excluded.ram_estimate_basis,
  ram_source_urls=excluded.ram_source_urls,
  storage_estimate_min_gb=excluded.storage_estimate_min_gb,
  storage_estimate_max_gb=excluded.storage_estimate_max_gb,
  storage_estimate_kind=excluded.storage_estimate_kind,
  storage_estimate_confidence=excluded.storage_estimate_confidence,
  storage_estimate_basis=excluded.storage_estimate_basis,
  storage_source_urls=excluded.storage_source_urls,
  checked_at=now(),updated_at=now();

update public.self_host_app_install_options io set
  options=coalesce((select jsonb_agg(option || jsonb_build_object(
      'source_url',coalesce(option->>'source_url',option->>'url'),
      'image',nullif(option->>'image','')
    ) order by coalesce((option->>'sort_order')::integer,0))
    from jsonb_array_elements(r.item->'install_options') option),'[]'::jsonb),
  docker_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='docker' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  docker_images=coalesce(array(select distinct option->>'image' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='docker' and nullif(option->>'image','') is not null order by option->>'image'),'{}'::text[]),
  compose_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='compose' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  truenas_scale_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='truenas_scale' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  unraid_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='unraid' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  umbrel_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='umbrel' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  yunohost_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='yunohost' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  casaos_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='casaos' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  runtipi_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='runtipi' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  cosmos_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='cosmos' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  openmediavault_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='openmediavault' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  synology_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='synology' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  qnap_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='qnap' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  proxmox_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='proxmox' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  home_assistant_os_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='home_assistant_os' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  kubernetes_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='kubernetes' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  helm_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='helm' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  native_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='native' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  binary_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='binary' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  package_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='package' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  other_urls=coalesce(array(select option->>'url' from jsonb_array_elements(r.item->'install_options') option where option->>'method'='other' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  source_urls=coalesce(array(select distinct coalesce(nullif(option->>'source_url',''),option->>'url') from jsonb_array_elements(r.item->'install_options') option order by coalesce(nullif(option->>'source_url',''),option->>'url')),'{}'::text[]),
  catalog_sources='[]'::jsonb,
  checked_at=now(),updated_at=now()
from reviewed_self_host_no r
where io.app_id=(r.item->>'app_id')::uuid
  and r.item->>'directory_action'='retain';

do $verify$
begin
  if (select count(*)
      from reviewed_self_host_no r
      join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid
      join public.self_host_app_resource_estimates e on e.app_id=a.id
      join public.self_host_app_install_options io on io.app_id=a.id
      where r.item->>'directory_action'='retain'
        and a.published=true
        and a.data_checked_at::date=current_date
        and e.ram_estimate_kind='estimated'
        and e.storage_estimate_kind='estimated'
        and e.ram_source_urls is not null
        and e.storage_source_urls is not null
        and jsonb_array_length(io.options)>0) <> 13 then
    raise exception 'N/O estimate and install rows were not fully updated';
  end if;
  if (select count(*) from reviewed_self_host_no r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid where r.item->>'directory_action' like 'unpublish%' and a.published=false) <> 3 then
    raise exception 'N/O duplicate and mislabeled entries were not unpublished';
  end if;
end $verify$;

drop table reviewed_self_host_no;
commit;
